import{$ as e,et as t,pt as n,s as r}from"./chunks/framework.UEZ_pRuy.js";var i=JSON.parse(`{"title":"How it Works","description":"","frontmatter":{},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"guide/how-it-works.md","lastUpdated":1777024754000}`),a={name:`guide/how-it-works.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="how-it-works" tabindex="-1">How it Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it Works&quot;">​</a></h1><p><code>hashup</code> produces a deterministic hash in four steps:</p><ol><li><strong>Resolve the entry file</strong> against <code>baseDir</code> (defaults to <code>process.cwd()</code>).</li><li><strong>Walk the import graph</strong> starting at the entry. Each file is parsed with <a href="https://github.com/guybedford/es-module-lexer" target="_blank" rel="noreferrer"><code>es-module-lexer</code></a> to extract its static imports, which are then resolved with <a href="https://github.com/webpack/enhanced-resolve" target="_blank" rel="noreferrer"><code>enhanced-resolve</code></a> — the same resolver Webpack uses. This honors <code>tsconfig</code> paths, package <code>exports</code>, conditional exports, and extension resolution.</li><li><strong>Hash each file&#39;s content</strong> (SHA-256). Results are cached per absolute path so a file reachable through multiple paths is hashed once.</li><li><strong>Combine all hashes</strong> — the entry&#39;s graph plus any <code>extras</code> — into a single deterministic SHA-256 digest.</li></ol><h2 id="determinism" tabindex="-1">Determinism <a class="header-anchor" href="#determinism" aria-label="Permalink to &quot;Determinism&quot;">​</a></h2><p>The final hash depends only on:</p><ul><li>The resolved set of files</li><li>Each file&#39;s content</li><li>The order in which hashes are combined (stable for a given graph)</li></ul><p>It does <strong>not</strong> depend on:</p><ul><li>Timestamps</li><li>Absolute paths on disk (only file content)</li><li>The working directory (when <code>baseDir</code> is explicit)</li></ul><h2 id="what-is-not-included" tabindex="-1">What Is Not Included <a class="header-anchor" href="#what-is-not-included" aria-label="Permalink to &quot;What Is Not Included&quot;">​</a></h2><ul><li>Type-only imports (<code>import type</code>) — erased at compile time.</li><li>Dynamic imports whose specifier is not a static string literal.</li><li>Files outside the reachable import graph, unless passed via <code>extras</code>.</li><li><strong>Anything under <code>node_modules</code></strong>. Imports that resolve into <code>node_modules</code> are treated as opaque: they contribute nothing to the hash and their own imports are never walked. This keeps the graph bounded on large monorepos and avoids re-hashing code you didn&#39;t write.</li></ul><p>If you care about changes in those (e.g. a lockfile determining which package version is installed), pass them explicitly via <code>extras</code>. Adding your <code>pnpm-lock.yaml</code> / <code>package-lock.json</code> / <code>yarn.lock</code> captures every direct, transitive, and peer-dep change — including integrity bumps — in a single byte-accurate input.</p><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><p>By default <code>hashup()</code> writes nothing to stderr. Pass <code>logLevel</code> to opt in:</p><table tabindex="0"><thead><tr><th>Level</th><th>What you&#39;ll see</th></tr></thead><tbody><tr><td><code>silent</code></td><td>Nothing. Default for programmatic use.</td></tr><tr><td><code>warn</code></td><td>Files that could not be hashed (read or parse failures).</td></tr><tr><td><code>info</code></td><td>Higher-level progress messages.</td></tr><tr><td><code>debug</code></td><td>Per-file decisions, including which <code>node_modules</code> paths were skipped.</td></tr></tbody></table><p>The CLI accepts <code>--log-level &lt;level&gt;</code> / <code>-l</code>, and <code>hashup.json</code> accepts a top-level <code>&quot;logLevel&quot;</code> field. The CLI flag wins when both are set.</p><h2 id="caveats" tabindex="-1">Caveats <a class="header-anchor" href="#caveats" aria-label="Permalink to &quot;Caveats&quot;">​</a></h2><ul><li><strong>Circular imports</strong> terminate deterministically, but the exact hash of a cycle depends on which member was the entry point — the cache is seeded with the entry&#39;s content hash first, so cycle re-visits return that placeholder. Entering the same cycle from a different file produces a different (still deterministic) hash.</li></ul>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};